import { RiskAssessmentChangesPreviousExposure } from './risk-assessment-changes-previous-exposure';
import { RiskAssessmentChangesPreviousPublicExploit } from './risk-assessment-changes-previous-public-exploit';
import { RiskAssessmentChangesPreviousVulnerableFunctionUsage } from './risk-assessment-changes-previous-vulnerable-function-usage';
/**
 * All changes of the risk assessment.
 */
export interface RiskAssessmentChanges {
    /**
     * The delta of the risk score.
     */
    deltaBaseRiskScore?: number;
    /**
     * The delta of the number of currently affected nodes.
     */
    deltaNumberOfAffectedNodes?: number;
    /**
     * The delta of the number of currently affected process groups.
     */
    deltaNumberOfAffectedProcessGroups?: number;
    /**
     * The delta of the number of data assets that are currently reachable by affected entities.
     */
    deltaNumberOfReachableDataAssets?: number;
    /**
     * The delta of the number of related attacks.
     */
    deltaNumberOfRelatedAttacks?: number;
    /**
     * The delta of the Davis risk score.
     */
    deltaRiskScore?: number;
    previousExposure?: RiskAssessmentChangesPreviousExposure;
    previousPublicExploit?: RiskAssessmentChangesPreviousPublicExploit;
    previousVulnerableFunctionUsage?: RiskAssessmentChangesPreviousVulnerableFunctionUsage;
}
